const $=s=>document.querySelector(s);
function loadPref(k,fallback){try{return JSON.parse(localStorage.getItem('aeris-'+k))??fallback;}catch{return fallback;}}
function savePref(k,v){try{localStorage.setItem('aeris-'+k,JSON.stringify(v));}catch{}}
const now=()=>Date.now()/1000;

// ——— Data path: native app bridge, a proxy, or (for browsers without either) the demo. ———
const BUILD_PROXY=typeof __AERIS_PROXY__!=='undefined'?__AERIS_PROXY__:'';
const staticHost=!['http:','https:'].includes(location.protocol)||location.hostname==='appassets.androidplatform.net'||location.hostname.endsWith('.github.io');
const defaultProxy=()=>BUILD_PROXY||(staticHost?null:location.origin+'/api/proxy');
setProxy(loadPref('proxy',null)||defaultProxy());
const canLive=()=>Boolean(bridge()||getProxy());

const state={nav:'explore',tab:'overview',selected:null,airport:null,mode:canLive()?'live':'demo',view3d:false,studio:false,camera:'chase',demoTime:410,playing:false,rate:1,
 flights:demoFlights(410),saved:loadPref('saved',[]),savedMeta:loadPref('savedMeta',{}),units:loadPref('units','aviation'),filter:{min:0,max:60000,type:'all',ground:true},
 replayTime:null,quality:loadPref('quality','high'),mapStyle:loadPref('mapStyle','map'),projection:loadPref('projection','globe'),error:'',info:{},center:{lat:1.36,lng:103.99},zoom:6.6};
let emptyHadAircraft=false,studio=null,lastUI=0,lastMapPush=0,lastFrame=0,lastTrail=0,lastSlow=0,toastTimer,dialogFocus,infoFor=null;

$('#app').innerHTML=`
<header class="topbar"><button class="brand" data-action="explore" aria-label="Aeris home"><svg viewBox="0 0 32 36" aria-hidden="true"><path d="M2 27 16 3l14 24-14-7Z" fill="#204e51"/><path d="m6 30 10-6 10 6-10 5Z" fill="#d87852"/></svg><span>AERIS<span class="brand-sub">A CLOSER LOOK AT FLIGHT</span></span></button><nav class="nav" aria-label="Main navigation"><button data-action="explore" class="active">Explore</button><button data-action="saved">Saved<span class="saved-count"></span></button><button data-action="airports">Airports</button></nav><div class="top-actions"><button id="source-pill" class="source-pill" data-action="connect" title="Flight data sources"><span class="dot"></span><span id="source-text">CONNECTING</span></button><time class="clock" id="clock"></time><button class="iconbutton" data-action="settings" aria-label="Settings" title="Settings">${icon('settings')}</button></div></header>
<div class="workspace"><aside class="rail" aria-label="Map navigation"><button class="active" data-action="explore" aria-label="Explore flights" title="Explore flights">${icon('map')}</button><button data-action="globe" aria-label="Globe or flat map" title="Globe or flat map">${icon('globe')}</button><button data-action="saved" aria-label="Saved flights" title="Saved flights">${icon('star')}</button><button data-action="airports" aria-label="Airport guide" title="Airport guide">${icon('airport')}</button><div class="rail-bottom"><button data-action="connect" aria-label="Data sources" title="Data sources">${icon('signal')}</button><button data-action="settings" aria-label="Display settings" title="Display settings">${icon('settings')}</button><button data-action="help" aria-label="Help and controls" title="Help and controls">${icon('help')}</button></div></aside>
<main class="stage" aria-label="Flight map"><div class="map-canvas" id="map" aria-label="World map of live aircraft. Drag to pan, pinch or scroll to zoom. Find aircraft using the search field."></div><div class="scene-container" id="scene"></div>
<div class="search-area"><div class="search-box">${icon('search')}<label class="sr-only" for="search">Find a flight, aircraft or airport</label><input id="search" placeholder="Flight, registration, airport…" autocomplete="off" autocapitalize="characters" aria-controls="search-results" aria-expanded="false"><kbd>/</kbd></div><div class="search-results" id="search-results"></div><div class="map-context"><button class="chip accent" data-action="nearby">${icon('plane')}<span id="flight-count">— aircraft</span></button><button class="chip" data-action="filters">${icon('filter')}<span id="filter-label">Filters</span></button><button class="chip" data-action="layers">${icon('layers')}Layers</button></div></div>
<div class="map-tools"><div class="tool-group"><button class="compass" data-action="north" aria-label="Reset bearing and tilt" title="Reset bearing and tilt"><span>N</span></button></div><div class="tool-group"><button data-action="zoom-in" aria-label="Zoom in" title="Zoom in">${icon('plus')}</button><button data-action="zoom-out" aria-label="Zoom out" title="Zoom out">${icon('minus')}</button></div><div class="tool-group"><button data-action="recenter" aria-label="Centre the selected aircraft" title="Centre the selected aircraft">${icon('locate')}</button><button data-action="locate-me" aria-label="Show aircraft near me" title="Show aircraft near me">${icon('me')}</button><button data-action="satellite" aria-label="Satellite or map" title="Satellite or map">${icon('satellite')}</button></div></div>
<div class="map-title"><div class="overline" id="map-overline">LIVE OVER</div><h1 id="map-heading">The whole sky.</h1><p id="map-subtitle">Live aircraft on an OpenStreetMap world.</p></div><div class="region-label" id="region-label">${icon('locate')}<span></span></div><div class="error-inline" role="status" id="feed-error"></div>
<div class="scene-overlay"><div class="scene-top"><button class="back-map" data-action="map">${icon('back')}Back to map</button><div class="scene-tag"><strong id="scene-callsign">—</strong><span id="scene-source">LIVE</span></div></div><div class="scene-actions"><button data-action="scene-style" aria-label="Satellite or map ground" title="Satellite or map ground">${icon('satellite')}</button><button data-action="reset-camera" aria-label="Reset camera" title="Reset camera">${icon('locate')}</button></div><div class="scene-caption"><strong id="scene-title">Real terrain, real position.</strong><span id="scene-fidelity">Altitude basis appears here</span><br><span>Attitude between reports is estimated.</span></div><div class="scene-help" id="scene-help">Following behind · pinch or scroll to change distance</div><div class="camera-bar" role="group" aria-label="Camera view"><button data-camera="orbit">${icon('orbit')}Orbit</button><button data-camera="chase" class="active">${icon('chase')}Follow</button><button data-camera="cockpit">${icon('eye')}Cockpit</button><button data-camera="model">${icon('cube')}Model</button></div></div>
<button class="mobile-detail-toggle" data-action="toggle-detail">${icon('plane')}<span id="mobile-flight-name">Details</span>${icon('arrow')}</button>
<div class="bottom-playback"><button class="play" data-action="play" aria-label="Play replay" title="Play or pause">${icon('play')}</button><div class="time-track"><div class="track-labels"><strong id="playback-label">LIVE</strong><span id="playback-phase">—</span></div><label class="sr-only" for="timeline">Replay position</label><input id="timeline" type="range" min="0" max="690" step="1" value="410"></div><span class="time-readout" id="time-readout">—</span><button class="speed" data-action="rate" title="Replay speed">1×</button><button class="live-return" data-action="return-live" id="return-live">LIVE ${icon('clock')}</button></div><div class="credits"><span id="map-credit"></span><button data-action="sources">Data, credits & accuracy ${icon('info')}</button></div></main>
<aside class="detail" aria-label="Flight details" id="detail"></aside></div><dialog id="dialog" aria-labelledby="dialog-title"></dialog><div class="toast" role="status" aria-live="polite" id="toast"></div>`;

// ——— Map and live feed ———
const map=new WorldMap($('#map'),{onSelect:id=>selectFlight(id),onAirport:selectAirport,onMove:onMapMove,onStyle:html=>{$('#map-credit').innerHTML=html;},onError:msg=>toast(msg),onReady:()=>{map.setProjection(state.projection);if(state.mapStyle!=='map')map.setStyle(state.mapStyle);}});
const live=new LiveFeed({storage:(()=>{try{return localStorage;}catch{return null;}})(),onUpdate:()=>{if(state.mode==='live')updateTrail(true);},onStatus:()=>renderSource()});
for(const id of loadPref('disabledProviders',[]))live.setEnabled(id,false);
loadAirports().then(()=>{map.setAirports(airportsGeoJSON());renderMapTitle();if(state.nav==='airports')renderDetail();});
// Without WebGL there is no map to report a viewport: poll a region around the last view so
// search, lists, details and airports still work.
if(!map.ok){const v=loadPref('view',null),c=v?.center||[103.99,1.36];onMapMove({west:c[0]-4,east:c[0]+4,south:c[1]-3,north:c[1]+3},7,{lng:c[0],lat:c[1]});}
function onMapMove(bounds,zoom,center){state.center=center;state.zoom=zoom;live.setView(bounds,zoom);renderMapTitle();}

const selected=()=>currentFlights().find(f=>f.id===state.selected)||null;
function currentFlights(){
 if(state.mode==='demo')return state.flights;
 if(state.replayTime!==null){const f=live.get(state.selected);const p=[...live.track(state.selected)].reverse().find(p=>p.positionTime<=state.replayTime);return f&&p?[{...f,...p}]:[];}
 return live.list();
}
function displayFlight(f){return state.mode==='live'&&state.replayTime===null?(live.position(f.id)||f):f;}
function passes(f){const alt=f.altitude??f.geometricAltitude;return (alt===null||f.onGround||alt>=state.filter.min&&alt<=state.filter.max)&&(state.filter.type==='all'||f.type===state.filter.type)&&(state.filter.ground||!f.onGround)&&(state.mode==='demo'||state.replayTime!==null||quality(f).age<=LIMITS.lost);}
function visibleFlights(){return currentFlights().filter(passes);}
const stale=f=>!f.simulated&&state.replayTime===null&&quality(f).age>LIMITS.stale;

// ——— Formatting ———
function fmt(v,kind,digits=0){if(v===null||v===undefined||!Number.isFinite(v))return '—';let n=v;if(state.units==='metric'){if(kind==='alt')n*=FT;if(kind==='speed')n*=KT*3.6;if(kind==='vertical')n*=FT/60;}return new Intl.NumberFormat('en-SG',{maximumFractionDigits:digits,minimumFractionDigits:digits}).format(n);}
function unit(kind){return state.units==='metric'?({alt:'m',speed:'km/h',vertical:'m/s'}[kind]||kind):({alt:'ft',speed:'kt',vertical:'ft/min'}[kind]||kind);}
function phase(f){if(f.onGround)return 'On ground';if(f.verticalRate===null)return 'In flight';return f.verticalRate<-250?'Descending':f.verticalRate>250?'Climbing':'Level';}
function shortTime(t){return Math.floor(t/60).toString().padStart(2,'0')+':'+Math.floor(t%60).toString().padStart(2,'0');}
function ago(s){return s<1?'just now':s<90?Math.round(s)+' s ago':s<5400?Math.round(s/60)+' min ago':'over an hour ago';}
function dataStatus(f){if(f.simulated)return 'Synthetic scenario · not a live flight';if(state.replayTime!==null)return 'Recorded in this session';const q=quality(f);return `${q.status} position · ${f.source} · reported ${ago(q.age)}`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
const nacpText=n=>n==null?'Not reported':({11:'< 3 m',10:'< 10 m',9:'< 30 m',8:'< 93 m',7:'< 185 m',6:'< 556 m',5:'< 926 m'})[n]||'> 1 km';
const operatorName=f=>state.info.route?.airline?.name||f.operator||state.info.aircraft?.owner||f.airline||null;

function renderNav(){document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.action===state.nav));document.querySelectorAll('.rail>button').forEach(b=>b.classList.toggle('active',b.dataset.action===state.nav));$('.saved-count').textContent=state.saved.length?' · '+state.saved.length:'';}
function selectFlight(id,{fly=false}={}){
 const f=currentFlights().find(f=>f.id===id);if(!f){toast('This aircraft is not in the current feed.');return;}
 state.selected=id;state.nav='explore';state.airport=null;state.replayTime=null;state.playing=false;live.setFocus(id);
 $('#search').value='';closeSearch();renderNav();loadInfo(f);renderDetail();renderPlayback();updateTrail(true);
 if(fly){const d=displayFlight(f);map.flyTo(d.lat,d.lon,Math.max(map.getZoom(),8));}
 if(state.view3d){map.model.setFlight(displayFlight(f),typeFor(f.type,f.category).code);map.resetCamera(f);if(state.studio)studio?.show(f);}
 if(innerWidth<=800)$('.workspace').classList.add('detail-open');
 pushMap(true);
}
function deselect(){state.selected=null;live.setFocus(null);state.info={};infoFor=null;map.setSelected(null);map.setTrail([]);map.setRoute(null);renderDetail();}
async function loadInfo(f){
 if(f.simulated){state.info={route:demoRoute(f)};infoFor=f.id;updateRoute();return;}
 if(infoFor===f.id)return;infoFor=f.id;state.info={loading:true};const id=f.id;
 const [r,a,p]=await Promise.allSettled([routeFor(f.flight||f.callsign),aircraftFor(id),photoFor(id,f.registration)]);
 if(state.selected!==id)return;
 state.info={route:r.value||null,aircraft:a.value||null,photo:p.value||null};
 renderDetail();updateRoute();
}
function demoRoute(f){const o=airportByCode(f?.route?.[0]),d=airportByCode(f?.route?.[1]);return o&&d?{origin:o,destination:d,airline:{name:f.airline},source:'demo'}:null;}
function routeCheck(f){const r=state.info.route;if(!r?.origin||!r?.destination)return null;if(f.simulated)return {plausible:true,progress:null};return routeFit(displayFlight(f),[r.origin.lat,r.origin.lon],[r.destination.lat,r.destination.lon]);}
function updateRoute(){const f=selected();if(!f){map.setRoute(null);return;}const r=state.info.route,fit=routeCheck(f);if(r&&fit?.plausible)map.setRoute(r.origin,r.destination,f.simulated?null:displayFlight(f));else map.setRoute(null);}
function updateTrail(force=false){const t=performance.now();if(!force&&t-lastTrail<900)return;lastTrail=t;const f=selected();if(!f||!map.trails){map.setTrail([]);return;}
 if(f.simulated){map.setTrail(scenarioTrack(f.id).filter(p=>p.scenarioSeconds<=state.demoTime),f);return;}
 const pts=live.track(f.id);map.setTrail(state.replayTime===null?pts:pts.filter(p=>p.positionTime<=state.replayTime),state.replayTime===null?displayFlight(f):null);}
function selectAirport(id){state.airport=airportByCode(id);if(!state.airport)return;state.nav='airports';if(state.view3d)closeScene();map.flyTo(state.airport.lat,state.airport.lon,Math.max(map.getZoom(),10));renderNav();renderDetail();if(innerWidth<=800)$('.workspace').classList.add('detail-open');closeSearch();}
/** Push aircraft positions to the map. Rate adapts to how many are on screen. */
function pushMap(force=false){
 const t=performance.now(),list=visibleFlights(),interval=list.length<1500?110:list.length<5000?220:450;
 if(!force&&t-lastMapPush<interval)return;lastMapPush=t;
 map.setFlights(list.map(displayFlight),state.selected,iconClass,stale);
 const f=selected();map.setSelected(f?displayFlight(f):null,f?iconClass(f):null);
 $('#flight-count').textContent=list.length.toLocaleString('en-SG')+' aircraft';
 const fl=state.filter;$('#filter-label').textContent=fl.min>0||fl.max<60000||fl.type!=='all'||!fl.ground?'Filters · on':'Filters';
}
function renderMapTitle(){
 const c=state.center,z=state.zoom;let place=null;
 if(z>=4.2){const near=nearestAirports(c.lat,c.lng,1,'L')[0];if(near&&near.distanceKm<Math.max(80,600/2**(z-4)))place=near.city||near.name;}
 $('#map-overline').textContent=state.mode==='live'?'LIVE OVER':'DEMO OVER';$('#map-heading').textContent=place?`Around ${place}.`:z<3?'The whole sky.':'The open sky.';
 $('#region-label span').textContent=`${Math.abs(c.lat).toFixed(2)}° ${c.lat>=0?'N':'S'}   ${Math.abs(c.lng).toFixed(2)}° ${c.lng>=0?'E':'W'}`;
}
function row(k,v){return `<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`;}
function metric(label,value,kind,key,ic,note=''){return `<button class="metric" data-metric="${key}"><span class="metric-label">${icon(ic)}${label}</span><span class="metric-value" data-value="${key}">${fmt(value,kind,kind==='vertical'&&state.units==='metric'?1:0)}<small>${unit(kind)}</small></span><span class="metric-note">${note}</span></button>`;}
function chart(f){let history=f.simulated?scenarioTrack(f.id):live.track(f.id);history=history.filter(p=>p.altitude!==null);if(history.length<2)return '<div class="notice">The altitude profile appears after two position reports. Nothing is invented between missing reports.</div>';const max=Math.max(1000,...history.map(p=>p.altitude));let d=history.map((p,i)=>`${i?'L':'M'}${(i/(history.length-1)*280).toFixed(1)},${(64-Math.max(0,p.altitude)/max*55).toFixed(1)}`).join(' ');const x=f.simulated?state.demoTime/690*280:280;return `<div class="chart-heading">Altitude profile<span>${f.simulated?'SIMULATED':'THIS SESSION'} · ${unit('alt')}</span></div><svg class="alt-chart" viewBox="0 0 280 78" role="img" aria-label="${f.simulated?'Simulated':'Recorded'} altitude profile"><defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8caa8d" stop-opacity=".25"/><stop offset="1" stop-color="#8caa8d" stop-opacity=".02"/></linearGradient></defs><path d="M0 20H280M0 43H280M0 65H280" stroke="#e7ece5" stroke-dasharray="3 4"/><path d="${d}L280 70H0Z" fill="url(#chartfill)"/><path d="${d}" fill="none" stroke="#729b7f" stroke-width="1.8"/><path d="M${x} 5V70" stroke="#d37d55" stroke-width="1" stroke-dasharray="2 3"/><circle cx="${x}" cy="${64-Math.max(0,f.altitude??0)/max*55}" r="3" fill="#d37d55" stroke="#fff" stroke-width="1.5"/></svg><div class="chart-axis"><span>${f.simulated?'Scenario start':'First report'}</span><span>${f.simulated?'Touchdown & rollout':'Most recent report'}</span></div>`;}
function flightItem(f,extra=''){return `<button class="flight-list-item" data-flight="${e(f.id)}"><span class="airline-monogram">${e((f.callsign||'?').slice(0,2))}</span><span><strong>${e(f.callsign)}</strong><small>${e(extra||f.operator||f.airline||f.registration||f.description||f.source||'')}</small></span><span class="item-end"><strong>${e(f.type||'—')}</strong><small>${f.onGround?'On ground':fmt(f.altitude,'alt')+' '+unit('alt')}</small></span>${icon('arrow')}</button>`;}
function routeHTML(f){
 const r=state.info.route,fit=r?routeCheck(f):null;
 const end=(a,cls='')=>`<div class="${cls}"><div class="airport-code">${e(a.iata||a.icao||'—')}</div><div class="route-place">${e(a.city||a.name||'')}</div></div>`;
 if(r&&fit&&fit.plausible){const pct=fit.progress===null?null:Math.round(fit.progress*100);
  return `<div class="route-points">${end(r.origin)}<div class="route-line">${icon('plane')}</div>${end(r.destination,'route-end')}</div>${pct===null?'':`<div class="route-progress" role="img" aria-label="${pct}% of the route flown"><span style="width:${pct}%"></span></div><div class="route-meta"><span>${Math.round(fit.totalKm-fit.remainingKm).toLocaleString('en-SG')} km flown</span><span>${Math.round(fit.remainingKm).toLocaleString('en-SG')} km to go</span></div>`}`;}
 if(r&&fit&&!fit.plausible)return `<div class="route-points"><div><div class="airport-code" style="font-size:19px">Route uncertain</div><div class="route-place">The database lists ${e(r.origin.iata||r.origin.icao)} → ${e(r.destination.iata||r.destination.icao)} for ${e(f.callsign)}, but this aircraft is ${Math.round(fit.crossTrackKm)} km off that path or heading elsewhere. Not shown.</div></div></div>`;
 if(state.info.loading)return '<div class="route-points"><div><div class="airport-code" style="font-size:19px">Looking up route…</div><div class="route-place">Checking public flight-route databases.</div></div></div>';
 return `<div class="route-points"><div><div class="airport-code" style="font-size:19px">Route unavailable</div><div class="route-place">No published route for this callsign. ADS-B positions alone do not establish one.</div></div></div>`;
}
function photoHTML(){const p=state.info.photo;if(!p?.src)return '';return `<figure class="airframe-photo"><a href="${e(p.link)}" target="_blank" rel="noreferrer"><img src="${e(p.src)}" alt="Photo of this aircraft" loading="lazy" decoding="async"${p.width?` width="${p.width}" height="${p.height}"`:''}></a><figcaption>© ${e(p.photographer)} · <a href="${e(p.link)}" target="_blank" rel="noreferrer">Planespotters.net</a></figcaption></figure>`;}
const titleCase=s=>String(s).toLowerCase().replace(/\b[a-z]/g,c=>c.toUpperCase());
function familyText(s){return ({heavy:'Wide-body',jumbo:'Wide-body, four engines',narrow:'Narrow-body',regional:'Regional jet',turboprop:'Turboprop',biz:'Business aircraft',light:'Light aircraft',heli:'Helicopter'})[s.cls]||'Aircraft';}
function engineText(s){if(s.generic)return 'Not known';if(s.rotor)return 'Turbine (rotorcraft)';return `${s.eng} × ${s.prop?'propeller':'jet'}${s.mount==='tail'?', rear-mounted':s.mount==='tri'?', two under the wings and one in the tail':''}`;}
function liveHint(){return `<div class="notice"><strong>Want real aircraft?</strong><br>Browsers cannot read the public ADS-B feeds directly. Install the Aeris app on your iPhone or Android phone, or connect a data proxy, for live traffic worldwide.<br><button class="small-link" data-action="connect" style="margin-top:6px;padding:0">How to get live data →</button></div>`;}
function renderDetail(){
 if(state.nav==='saved'){const available=currentFlights();const cards=state.saved.map(id=>available.find(f=>f.id===id)||state.savedMeta[id]).filter(Boolean);$('#detail').innerHTML=`<div class="detail-inner"><div class="detail-caption">YOUR COLLECTION<button class="iconbutton detail-close" style="display:none" data-action="toggle-detail" aria-label="Close details">${icon('close')}</button></div><div class="list-header"><h2>Saved flights.</h2><p>A small corner of the sky, just for you.<br>Saved on this device.</p></div>${cards.length?cards.map(f=>flightItem(f)).join(''):`<div class="empty">${icon('star')}<p>No flights saved yet.<br>Open a flight and tap the star.</p></div>`}${cards.length>=2?`<button class="secondary wide" data-action="compare" style="margin-top:24px">${icon('compare')} Compare saved flights</button>`:''}${cards.length?'<p class="fact-note">A saved flight may be outside the feed or no longer airborne. Stored details are a snapshot.</p><button class="secondary wide" data-action="clear-saved" style="margin-top:14px">Clear saved list</button>':''}</div>`;return;}
 if(state.nav==='airports'){renderAirports();return;}
 const f=selected();
 if(!f){const n=visibleFlights().length;$('#detail').innerHTML=`<div class="detail-inner"><div class="detail-caption">FLIGHT EXPLORER<button class="iconbutton detail-close" style="display:none" data-action="toggle-detail" aria-label="Close details">${icon('close')}</button></div><h2>Your next discovery.</h2><div class="empty">${icon('plane')}<p>${state.mode==='live'?(n?'Tap an aircraft on the map, or search by flight, registration or airport.':'Waiting for live positions in this part of the sky…'):'Choose an aircraft on the map, or use the search.'}</p></div><button class="secondary wide" data-action="nearby">Browse aircraft in view</button>${state.mode==='demo'&&!canLive()?liveHint():''}</div>`;return;}
 const t=typeFor(f.type,f.category),spec=t.spec,info=state.info,tabs=['overview','aircraft','telemetry'];
 let content='';
 if(state.tab==='overview'){content=`${photoHTML()}<div class="metric-grid">${metric('Barometric altitude',f.altitude,'alt','altitude','altitude',f.simulated?'Simulated':f.onGround?'On ground':'Pressure, 1013.25 hPa')}${metric('Ground speed',f.groundSpeed,'speed','groundSpeed','speed','Over the ground')}${metric('Vertical speed',f.verticalRate,'vertical','verticalRate','vertical',f.verticalRate<-50?'Descending':f.verticalRate>50?'Climbing':'Level / unavailable')}${metric('Ground track',f.track,'°','track','heading','Direction of travel')}</div><div id="altitude-chart">${chart(f)}</div>`;}
 else if(state.tab==='aircraft'){const a=info.aircraft,reg=f.registration||a?.registration;content=`${photoHTML()}<h3>${e(f.description&&!t.exact?titleCase(f.description):spec.name)}</h3><p class="fact-note" style="margin-top:5px">${e(t.exact?spec.maker+' · '+familyText(spec):t.code?'Type not reported · model chosen from its size category':'Type not reported')}</p><dl class="fact-list">${row('Registration',reg||'Not reported')}${row('ICAO type',f.type||a?.icaoType||'Not reported')}${a?.type?row('Variant',a.type):''}${row('Operator',operatorName(f)||'Not reported')}${a?.owner&&a.owner!==operatorName(f)?row('Registered owner',a.owner):''}${a?.country?row('Registered in',a.country):''}${f.year?row('Year built',f.year):''}${row('Length · span · height',`${spec.length} · ${spec.span} · ${spec.height} m`)}${row('Engines',engineText(spec))}${row('ICAO 24-bit address',f.simulated?'Synthetic aircraft':f.id.toUpperCase())}${f.military?row('Category','Military (database flag)'):''}</dl><p class="geometry-note">${t.exact?'Reference dimensions for this type. The 3D model is an original parametric model: proportions and layout match the type; the exact airframe, engines and livery are not modelled.':'Type unknown: the 3D model is a representative aircraft of the reported size category.'}</p>`;}
 else{const msl=altitudeMSL(f),d=displayFlight(f),age=quality(f).age;content=`<div class="metric-grid">${metric('Indicated airspeed',f.indicatedAirspeed,'speed','indicatedAirspeed','speed','Only if reported')}${metric('True airspeed',f.trueAirspeed,'speed','trueAirspeed','speed','Only if reported')}</div><dl class="fact-list">${row('Mach',f.mach==null?'Not reported':f.mach.toFixed(3))}${row('Geometric altitude',f.geometricAltitude==null?'Not reported':fmt(f.geometricAltitude,'alt')+' '+unit('alt')+' (GNSS, ellipsoid)')}${row('Height above sea level',msl.metres===null?'Unavailable':fmt(msl.metres/FT,'alt')+' '+unit('alt')+' · '+msl.basis)}${row('Selected altitude',f.navAltitude==null?'Not reported':fmt(f.navAltitude,'alt')+' '+unit('alt'))}${row('Selected heading',f.navHeading==null?'Not reported':Math.round(f.navHeading)+'°')}${row('Altimeter setting',f.navQnh==null?'Not reported':f.navQnh.toFixed(1)+' hPa')}${row('Wind',f.windDirection==null||f.windSpeed==null?'Not reported':`${Math.round(f.windDirection)}° at ${fmt(f.windSpeed,'speed')} ${unit('speed')}`)}${row('Outside air',f.outsideTemp==null?'Not reported':f.outsideTemp+' °C')}${row('True heading',f.trueHeading==null?'Not reported':Math.round(f.trueHeading)+'°')}${row('Roll angle',f.roll==null?'Not reported':f.roll.toFixed(1)+'°')}${row('Turn rate',f.trackRate==null?'Not reported':f.trackRate.toFixed(2)+'°/s')}${row('Squawk',f.squawk?(f.squawk+(f.emergency?' · '+f.emergency.toUpperCase():'')):'Not reported')}${row('Position',d.lat.toFixed(5)+'°, '+d.lon.toFixed(5)+'°')}${row('Position accuracy',nacpText(f.nacp))}${row('Position source',f.simulated?'Synthetic':f.source)}${row('Data from',f.simulated?'Scenario':(f.providers||[f.provider]).filter(Boolean).join(', '))}${row('Position age',f.simulated?'Simulated':age<3600?age.toFixed(1)+' s':'Unknown')}</dl><button class="secondary wide" style="margin-top:18px" data-action="export">${icon('download')} Export session track</button>`;}
 const status=f.simulated?'SIMULATED':state.replayTime!==null?'REPLAY':quality(f).status.toUpperCase();
 const fitNote=f.simulated?'Illustrative flight':info.route?(routeCheck(f)?.plausible?`Route from ${info.route.source}, matches position`:'Route not confirmed'):'Route not inferred';
 $('#detail').innerHTML=`<div class="detail-inner"><div class="detail-caption"><span>FLIGHT EXPLORER</span><span class="tag ${f.emergency?'alert':''}">${e(f.emergency?f.emergency.toUpperCase():status)}</span><button class="iconbutton detail-close" style="display:none" data-action="toggle-detail" aria-label="Close details">${icon('close')}</button></div><div class="airline-row"><span class="airline-monogram">${e(f.callsign.slice(0,2))}</span><div class="flight-heading"><h2>${e(f.callsign)}</h2><p>${e([info.route?.flightNumber,operatorName(f)||f.registration||'Unidentified operator'].filter(Boolean).join(' · '))}</p></div><button class="iconbutton ${state.saved.includes(f.id)?'saved-star':''}" data-action="save-flight" aria-label="${state.saved.includes(f.id)?'Unsave':'Save'} ${e(f.callsign)}" title="Save flight" aria-pressed="${state.saved.includes(f.id)}">${icon('star')}</button></div><div class="route-card">${routeHTML(f)}<div class="route-status"><span class="phase"><span class="dot"></span><span id="flight-phase">${phase(f)}</span></span><span>${e(fitNote)}</span></div></div><button class="view-card" data-action="3d" aria-label="Explore ${e(f.callsign)} in 3D"><span class="three-label">REAL TERRAIN · 3D</span>${planeSVG}<span class="view-label"><strong>Step into the flight.</strong><small>Follow, orbit or ride along over real ground</small></span><span class="view-arrow">${icon('arrow')}</span></button><div class="detail-tabs" role="tablist" aria-label="Flight information">${tabs.map(t=>`<button role="tab" aria-selected="${state.tab===t}" class="${state.tab===t?'active':''}" data-tab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div role="tabpanel">${content}</div><div class="data-source">${icon('signal')}<span><strong>${f.simulated?'Made for exploring. Labelled honestly.':'Know what you are seeing.'}</strong><span id="detail-data-status">${e(dataStatus(f))}</span><br>${f.simulated?'No real flight status or airline livery is implied.':'Motion between reports is estimated for at most '+LIMITS.extrapolate+' s.'}</span></div></div>`;
 $('#mobile-flight-name').textContent=f.callsign;$('#scene-callsign').textContent=f.callsign+' · '+(spec.name||'Aircraft');
}
function runwayPlan(a){
 const rw=a.runways.filter(r=>r.ends&&r.ends.flat().every(Number.isFinite));if(!rw.length)return '';
 const k=Math.cos(a.lat*Math.PI/180),xy=([la,lo])=>[(lo-a.lon)*k,-(la-a.lat)];
 const pts=rw.flatMap(r=>r.ends.map(xy)),xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);
 const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),span=Math.max((maxX-minX)/2.2,(maxY-minY),.004);
 const sc=110/span,cx=(minX+maxX)/2,cy=(minY+maxY)/2,P=p=>{const [x,y]=xy(p);return [150+(x-cx)*sc,67+(y-cy)*sc];},metresPerPx=span*111320/110;
 return `<div class="airport-plan"><svg viewBox="0 0 300 135" role="img" aria-label="Runway layout to scale">${rw.map(r=>{const [x1,y1]=P(r.ends[0]),[x2,y2]=P(r.ends[1]),w=Math.max(2.5,(r.width||45)/metresPerPx);return `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke="#70897e" stroke-width="${w.toFixed(1)}"/><line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke="#dbe5d6" stroke-width=".8" stroke-dasharray="4 4"/>`;}).join('')}</svg><span>RUNWAYS TO SCALE · NORTH UP</span></div>`;
}
function airportTraffic(a){
 return currentFlights().map(f=>({f,d:distance([a.lat,a.lon],[displayFlight(f).lat,displayFlight(f).lon])})).filter(({f,d})=>d<30000&&(f.onGround||(f.altitude??99999)<10000)).sort((x,y)=>x.d-y.d).slice(0,12)
  .map(({f,d})=>flightItem(f,(f.onGround?'On ground':f.verticalRate<-300?'Arriving':f.verticalRate>300?'Departing':'Nearby')+` · ${(d/1000).toFixed(1)} km`)).join('');
}
function renderAirports(){const a=state.airport;
 if(!a){const near=nearestAirports(state.center.lat,state.center.lng,14,'LM');$('#detail').innerHTML=`<div class="detail-inner"><div class="detail-caption">ON THE GROUND<button class="iconbutton detail-close" style="display:none" data-action="toggle-detail" aria-label="Close details">${icon('close')}</button></div><div class="list-header"><h2>Places of possibility.</h2><p>Airports nearest the centre of the map.<br>Runways, local time and traffic now.</p></div><div class="airport-list">${near.map(a=>`<button class="airport-card" data-airport="${e(a.id)}"><span class="airport-code">${e(a.iata||a.icao)}</span><span><strong>${e(a.name)}</strong><small>${e(a.icao)} · ${e(a.city||a.country)} · ${Math.round(a.distanceKm)} km</small></span>${icon('arrow')}</button>`).join('')}</div><div class="notice">Reference data from OurAirports. Active runways, NOTAMs, gates and operating conditions need current airport information.</div></div>`;return;}
 const lt=localTime(a),traffic=airportTraffic(a);
 $('#detail').innerHTML=`<div class="detail-inner"><div class="detail-caption"><button data-action="airports">${icon('back')} ALL AIRPORTS</button><span>${e(a.icao)}</span></div><div class="list-header"><h2>${e(a.name)}</h2><p>${e([a.city,a.country].filter(Boolean).join(' · '))} · ${e(a.iata||a.icao)}</p></div>${runwayPlan(a)}<dl class="fact-list">${row('ICAO / IATA',a.icao+' / '+(a.iata||'—'))}${row('Coordinates',Math.abs(a.lat).toFixed(4)+'° '+(a.lat>=0?'N':'S')+' · '+Math.abs(a.lon).toFixed(4)+'° '+(a.lon>=0?'E':'W'))}${row('Field elevation',a.elevation==null?'Unknown':fmt(a.elevation,'alt')+' '+unit('alt'))}${row('Local time',lt?lt+' · '+a.tz:'Time zone unknown')}</dl><div class="section-sub">RUNWAYS</div><dl class="fact-list">${a.runways.length?a.runways.map(r=>row(r.ident,r.length.toLocaleString('en-SG')+(r.width?' × '+r.width:'')+' m'+(r.surface?' · '+r.surface:''))).join(''):row('Runways','Not listed')}</dl><div class="section-sub">TRAFFIC NOW · WITHIN 30 KM</div>${traffic||`<div class="empty"><p>${state.mode==='live'?'No aircraft below 10,000 ft near this airport in the current feed.':'Connect live data to see traffic here.'}</p></div>`}<div class="notice">Runway figures are reference data, not a statement of operational availability.</div>${a.website?`<a class="secondary wide" style="display:block;text-align:center;text-decoration:none" href="${e(a.website)}" target="_blank" rel="noreferrer">Official airport website ↗</a>`:''}</div>`;
}
function renderClock(){const d=new Date();$('#clock').textContent=d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'})+' · '+d.toISOString().slice(11,16)+'Z';$('#clock').dateTime=d.toISOString();}
function renderSource(){
 const s=live.status(),pill=$('#source-pill');let label;
 if(state.mode==='demo')label=canLive()?'DEMO TRAFFIC':'DEMO · NO LIVE ACCESS';
 else if(state.replayTime!==null)label='SESSION REPLAY';
 else if(s.live){const age=Math.max(0,now()-(s.lastUpdate||now()));label=`LIVE · ${age<10?age.toFixed(1):Math.round(age)} s`;}
 else label=s.providers.some(p=>p.enabled&&p.reachable&&p.fail>0)?'LIVE · RECONNECTING':'CONNECTING';
 $('#source-text').textContent=label;pill.classList.toggle('live',state.mode==='live'&&s.live&&state.replayTime===null);pill.classList.toggle('error',state.mode==='live'&&!s.live&&s.providers.some(p=>p.fail>2));
}
function renderPlayback(){
 const demo=state.mode==='demo';$('.play').innerHTML=icon(state.playing?'pause':'play');$('.play').setAttribute('aria-label',state.playing?'Pause replay':'Play replay');$('.speed').textContent=state.rate+'×';
 const f=selected(),slider=$('#timeline');
 $('#playback-label').textContent=demo?'DEMO REPLAY':state.replayTime===null?'LIVE':'SESSION REPLAY';
 if(demo){$('#playback-phase').textContent=state.selected==='demo-tr18'?'Takeoff → climb':state.selected==='demo-sq228'?'Approach → landing':'Illustrative scenario';slider.min=0;slider.max=DEMO_DURATION;slider.disabled=false;slider.value=state.demoTime;$('#time-readout').textContent=shortTime(state.demoTime)+' / '+shortTime(DEMO_DURATION);$('.play').disabled=false;$('#return-live').textContent='RESET';}
 else{const h=f?live.track(f.id):[],start=h[0]?.positionTime||0,end=h.at(-1)?.positionTime||start;
  $('#playback-phase').textContent=f?(h.length>1?`${f.callsign} · ${h.length} reports recorded`:`${f.callsign} · recording…`):`${live.status().aircraft.toLocaleString('en-SG')} aircraft tracked`;
  slider.min=start;slider.max=end||1;slider.value=state.replayTime??end;slider.disabled=h.length<2;$('.play').disabled=h.length<2;$('#time-readout').textContent=h.length>1?shortTime((state.replayTime??end)-start):'—';$('#return-live').innerHTML='LIVE '+icon('clock');}
 renderSource();$('#feed-error').textContent=state.error;
}
function refresh(){renderNav();renderDetail();renderPlayback();pushMap(true);renderMapTitle();}
function closeSearch(){$('#search-results').classList.remove('open');$('#search').setAttribute('aria-expanded','false');}
function search(){
 const raw=$('#search').value.trim(),q=raw.toLowerCase();if(!q){closeSearch();return;}
 const found=currentFlights().filter(f=>[f.callsign,f.registration,f.type,f.operator,f.description,f.id,...f.route||[]].some(v=>String(v||'').toLowerCase().includes(q))).slice(0,7);
 const ap=searchAirports(q,5);
 const remote=state.mode==='live'&&/^[a-z0-9-]{3,8}$/i.test(raw)&&!found.some(f=>f.callsign.toLowerCase()===q);
 $('#search-results').innerHTML=found.map(f=>`<button class="result" data-flight="${e(f.id)}" data-fly="1">${icon('plane')}<span><b>${e(f.callsign)}</b><small>${e(f.operator||f.airline||f.registration||f.description||'Aircraft')}</small></span><span class="result-right">${e(f.type||'—')}</span></button>`).join('')+ap.map(a=>`<button class="result" data-airport="${e(a.id)}">${icon('airport')}<span><b>${e(a.iata||a.icao)}</b><small>${e(a.name)}</small></span><span class="result-right">${e(a.icao)}</span></button>`).join('')+(remote?`<button class="result" data-find="${e(raw)}">${icon('globe')}<span><b>Find ${e(raw.toUpperCase())} worldwide</b><small>Searches every live source by callsign, registration or hex</small></span></button>`:'')+(!found.length&&!ap.length&&!remote?'<div class="empty">No matches in this feed.<br>Try a callsign, registration or airport code.</div>':'');
 $('#search-results').classList.add('open');$('#search').setAttribute('aria-expanded','true');
}
async function findWorldwide(q){closeSearch();toast(`Searching live sources for ${q.toUpperCase()}…`);const ids=await live.find(q);if(!ids.length){toast(`${q.toUpperCase()} is not being received by any live source right now.`);return;}selectFlight(ids[0],{fly:true});}
function openDialog(title,body){const d=$('#dialog');dialogFocus=document.activeElement;d.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${e(title)}</h2><button class="iconbutton" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();}
function closeDialog(){if($('#dialog').open)$('#dialog').close();dialogFocus?.focus?.();}
$('#dialog').addEventListener('click',ev=>{if(ev.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeDialog();}});
function showFilters(){openDialog('Find your kind of flight.',`<p>Filter the aircraft on the map. Aircraft without an altitude report stay visible.</p><label class="form-field">Aircraft type<select id="filter-type"><option value="all">All aircraft</option>${[...new Set(currentFlights().map(f=>f.type).filter(Boolean))].sort().map(t=>`<option ${state.filter.type===t?'selected':''}>${e(t)}</option>`).join('')}</select></label><div class="form-row"><label class="form-field">Minimum altitude (ft)<input id="filter-min" type="number" min="0" max="60000" step="1000" value="${state.filter.min}"></label><label class="form-field">Maximum altitude (ft)<input id="filter-max" type="number" min="0" max="60000" step="1000" value="${state.filter.max}"></label></div><label class="switch-row"><span>Aircraft on the ground<small>Taxiing and parked aircraft that report a position</small></span><input type="checkbox" id="filter-ground" ${state.filter.ground?'checked':''}></label><div class="form-error" id="filter-error"></div><div class="button-row"><button class="primary" data-action="apply-filters">Apply filters</button><button class="secondary" data-action="reset-filters">Reset</button></div>`);}
function showLayers(){openDialog('A map with room to breathe.',`<p>OpenStreetMap geography at every zoom level, or satellite imagery.</p><div class="source-buttons">${[['map','Map'],['detail','Detailed'],['dark','Night'],['satellite','Satellite']].map(([k,l])=>`<button class="${state.mapStyle===k?'active':''}" data-style="${k}">${l}</button>`).join('')}</div>${[['globe','Globe view','The whole Earth as a sphere when zoomed out',state.projection==='globe'],['altitudeColors','Colour by altitude','Low aircraft warm, high aircraft cool',map.altitudeColors],['labels','Labels','Callsigns and airport codes',map.labels],['trails','Selected flight trail','Positions received in this session',map.trails],['airports','Airports','Worldwide airports; tap one for runways and traffic',map.airports]].map(([key,label,note,on])=>`<label class="switch-row"><span>${label}<small>${note}</small></span><input type="checkbox" data-layer="${key}" ${on?'checked':''}></label>`).join('')}<div class="button-row"><button class="primary" data-action="close-dialog">Done</button><button class="secondary" data-action="connect">Data sources</button><button class="secondary" data-action="settings">Settings</button></div>`);}
function showSettings(){openDialog('Make the sky your own.',`<label class="form-field">Units<select id="units"><option value="aviation" ${state.units==='aviation'?'selected':''}>Aviation · feet, knots, ft/min</option><option value="metric" ${state.units==='metric'?'selected':''}>Metric · metres, km/h, m/s</option></select></label><label class="form-field">Model view rendering<select id="render-quality"><option value="high">High detail</option><option value="low" ${state.quality==='low'?'selected':''}>Battery friendly</option></select><small>Battery mode lowers pixel resolution and turns off shadows in the model view.</small></label><div class="button-row"><button class="secondary" data-action="connect">Data sources</button><button class="secondary" data-action="layers">Map layers</button></div><p class="fact-note">Preferences and saved flights stay on this device. No account is needed.</p><div class="button-row"><button class="primary wide" data-action="save-settings">Save preferences</button></div>`);}
function environmentText(){const b=bridge();if(b)return `<strong>${b==='ios'?'iPhone/iPad app':'Android app'}.</strong> Flight data is fetched natively, so every source below is available.`;if(getProxy())return `<strong>Browser via proxy.</strong> Requests go through <code>${e(getProxy())}</code>.`;return `<strong>Browser only.</strong> Public ADS-B feeds do not allow web pages to read them. Use the Aeris app, or add a proxy below.`;}
function showConnect(){
 const s=live.status();const rows=s.providers.map(p=>{const def=PROVIDERS.find(x=>x.id===p.id);const st=!p.reachable?'Needs the app or a proxy':p.state==='ok'?`${p.ms} ms · ${p.aircraft} aircraft · ${ago(now()-p.lastOk)}`:p.state==='idle'?'Waiting':p.state==='limited'?'Rate limited · pausing':p.state==='refused'?'Refused this network':p.state==='blocked'?'Blocked by the browser':p.error||'Error';
  return `<label class="switch-row"><span>${e(def.name)}<small>${e(st)}${p.credits!=null?' · '+p.credits+' credits left today':''}<br>${e(def.terms)}</small></span><input type="checkbox" data-provider="${p.id}" ${p.enabled?'checked':''}></label>`;}).join('');
 openDialog('Connect to the real sky.',`<p>${environmentText()}</p><div class="source-buttons"><button class="${state.mode==='live'?'active':''}" data-action="use-live">Live traffic</button><button class="${state.mode==='demo'?'active':''}" data-action="use-demo">Demo scenario</button></div>${rows}<label class="form-field">Data proxy (optional, for browsers)<input id="proxy" type="url" value="${e(loadPref('proxy','')||'')}" placeholder="${e(BUILD_PROXY||'https://your-proxy.workers.dev/')}" spellcheck="false"><small>A proxy you run (for example the Cloudflare Worker in this project) that forwards requests to the sources above. Leave empty inside the app.</small></label><div class="form-error" id="connection-error"></div><div class="button-row"><button class="primary" data-action="save-proxy">Save</button><a class="secondary" href="https://github.com/shira421/aeris#live-data" target="_blank" rel="noreferrer" style="text-decoration:none;display:inline-flex;align-items:center">Install the app ↗</a></div><div class="notice">The area on screen is refreshed about once a second, alternating sources so each stays within its published limit. Polling pauses when Aeris is in the background.</div>`);
}
function useLive(){if(!canLive()){showConnect();$('#connection-error').textContent='This browser cannot read live sources. Install the app or add a proxy.';return;}state.playing=false;state.replayTime=null;state.mode='live';state.selected=null;state.info={};infoFor=null;live.start();closeDialog();refresh();toast('Live traffic on. Positions arrive within a few seconds.');}
function useDemo(){live.stop();state.mode='demo';state.demoTime=410;state.flights=demoFlights(410);state.selected='demo-sq228';state.replayTime=null;state.playing=false;state.error='';state.nav='explore';state.airport=null;state.info={route:demoRoute(state.flights[0])};infoFor='demo-sq228';if(state.view3d)closeScene();closeDialog();map.flyTo(1.36,103.99,8.5);refresh();updateRoute();}
// ——— 3D ———
function canPlace(f){return f.simulated||f.onGround||f.altitude!==null||f.geometricAltitude!==null;}
function openScene(camera='chase'){
 const f=selected();if(!f){toast('Choose an aircraft first.');return false;}
 if(!canPlace(f)){toast('This aircraft reports no altitude, so it cannot be placed in 3D.');return false;}
 if(!map.ok){toast('3D needs WebGL, which is unavailable here.');return false;}
 state.view3d=true;state.camera=camera;$('.workspace').classList.add('scene-mode');$('.workspace').classList.remove('detail-open');
 map.enter3D(displayFlight(f),{camera:camera==='model'?'chase':camera,style:state.mapStyle==='satellite'?null:'satellite'});
 setCamera(camera);renderDetail();return true;
}
function closeScene(){state.view3d=false;setStudio(false);$('.workspace').classList.remove('scene-mode','studio-mode');map.exit3D();const f=selected();if(f){const d=displayFlight(f);setTimeout(()=>map.flyTo(d.lat,d.lon,Math.max(8,Math.min(11,map.getZoom()))),50);}pushMap(true);}
function setStudio(on){state.studio=on;$('.workspace').classList.toggle('studio-mode',on);if(on){if(!studio){try{studio=new Studio($('#scene'),toast);studio.setQuality(state.quality);}catch{state.studio=false;$('.workspace').classList.remove('studio-mode');return;}}studio.active=true;studio.resize();const f=selected();if(f)studio.show(f);}else if(studio)studio.active=false;}
function setCamera(mode){
 state.camera=mode;setStudio(mode==='model');if(mode!=='model')map.setCamera(mode);
 document.querySelectorAll('[data-camera]').forEach(b=>{b.classList.toggle('active',b.dataset.camera===mode);b.setAttribute('aria-pressed',String(b.dataset.camera===mode));});
 $('#scene-help').textContent=mode==='orbit'?'Drag to orbit · pinch or scroll to move closer':mode==='chase'?'Following behind · pinch or scroll to change distance':mode==='cockpit'?'Reconstructed forward view · not an onboard camera':'Drag to orbit the model · scroll to zoom';
 $('#scene-title').textContent=mode==='model'?'The model, up close.':'Real terrain, real position.';
}
// ——— Definitions, sources, help ———
const definitions={
 altitude:['Barometric altitude','Altitude from air pressure, referenced to the standard 1013.25 hPa. It is what transponders report for separation, and it differs from height above sea level when the local pressure is not standard. The Telemetry tab shows the GNSS height and Aeris\'s best estimate of height above sea level.'],
 groundSpeed:['Ground speed','How fast the aircraft moves over the ground. Wind makes it different from airspeed. One knot is 1.852 km/h.'],
 verticalRate:['Vertical speed','The reported rate of climb or descent, from pressure altitude when available. Negative means descending.'],
 track:['Ground track','The direction the aircraft moves across the ground, clockwise from true north. Wind can make this differ from where the nose points.'],
 indicatedAirspeed:['Indicated airspeed','The cockpit airspeed from pitot/static pressure, shown only when the aircraft broadcasts it in extended reports. It cannot be derived from ground speed.'],
 trueAirspeed:['True airspeed','Speed relative to the surrounding air. It differs from both indicated airspeed and ground speed. Missing reports stay unavailable.']
};
function showSources(){openDialog('A clearer picture. Including the gaps.',`<p><strong>Live positions</strong><br>From community ADS-B and MLAT networks: adsb.lol (ODbL), adsb.fi, airplanes.live and the OpenSky Network. Each position keeps its own timestamp. Between reports Aeris estimates motion along the reported track and turn rate for at most ${LIMITS.extrapolate} seconds, marks positions stale after ${LIMITS.stale} seconds and removes them after ${LIMITS.lost}. Coverage depends on volunteer receivers: oceans and remote areas can be empty.</p><p><strong>Routes and airframes</strong><br>Routes come from adsbdb and hexdb, which list the usual route for a callsign. Aeris checks each route against where the aircraft is and where it is heading, and hides routes that do not fit. Registrations and owners come from adsbdb; photos from Planespotters.net, credited to each photographer.</p><p><strong>Map and 3D</strong><br>OpenStreetMap data through OpenFreeMap, satellite imagery from Esri, and terrain heights from AWS Terrain Tiles. In 3D, aircraft height uses GNSS altitude corrected with the EGM96 geoid where available, otherwise pressure altitude. Models are original and built from published dimensions; liveries are not modelled.</p><ul class="link-list"><li><a href="https://adsb.lol" target="_blank" rel="noreferrer">adsb.lol · ODbL 1.0</a></li><li><a href="https://adsb.fi" target="_blank" rel="noreferrer">adsb.fi · open data</a></li><li><a href="https://airplanes.live" target="_blank" rel="noreferrer">airplanes.live</a></li><li><a href="https://opensky-network.org" target="_blank" rel="noreferrer">The OpenSky Network</a></li><li><a href="https://www.adsbdb.com" target="_blank" rel="noreferrer">adsbdb · aircraft and routes</a></li><li><a href="https://www.planespotters.net" target="_blank" rel="noreferrer">Planespotters.net · photos</a></li><li><a href="https://openfreemap.org" target="_blank" rel="noreferrer">OpenFreeMap · © OpenStreetMap contributors</a></li><li><a href="https://ourairports.com/data/" target="_blank" rel="noreferrer">OurAirports · public-domain airports</a></li><li><a href="https://registry.opendata.aws/terrain-tiles/" target="_blank" rel="noreferrer">AWS Terrain Tiles</a></li><li><a href="https://threejs.org/" target="_blank" rel="noreferrer">Three.js and MapLibre GL JS</a></li></ul>`);}
function showHelp(){openDialog('A little closer to the sky.',`<p>Tap any aircraft for its route, airframe and telemetry. "Step into the flight" opens a 3D view over real terrain: follow behind, orbit, or look ahead from a reconstructed cockpit position.</p><div class="kbd-row"><span>Search flights & airports</span><kbd>/</kbd></div><div class="kbd-row"><span>Pan / orbit</span><kbd>Drag</kbd></div><div class="kbd-row"><span>Zoom</span><kbd>Scroll · pinch</kbd></div><div class="kbd-row"><span>Rotate and tilt the map</span><kbd>Right-drag · two fingers</kbd></div><div class="kbd-row"><span>Play / pause replay</span><kbd>Space</kbd></div><div class="kbd-row"><span>Back to the map</span><kbd>Esc</kbd></div><div class="notice">Search a callsign that is not on screen and choose "Find worldwide" to jump to it anywhere in the world.</div><button class="secondary wide" data-action="connect">Data sources</button>`);}
function compare(){const flights=state.saved.map(id=>currentFlights().find(f=>f.id===id)).filter(Boolean).slice(0,4);if(flights.length<2){toast('At least two saved flights must be in the current feed.');return;}openDialog('Side by side.',`<p>Comparing the first ${flights.length} saved flights in this feed.</p><table class="comparison"><tr><th>Flight</th>${flights.map(f=>`<th>${e(f.callsign)}</th>`).join('')}</tr>${[['Aircraft',f=>f.type||'—'],['Altitude',f=>fmt(f.altitude,'alt')+' '+unit('alt')],['Ground speed',f=>fmt(f.groundSpeed,'speed')+' '+unit('speed')],['Vertical speed',f=>fmt(f.verticalRate,'vertical')+' '+unit('vertical')],['Data',f=>f.simulated?'Simulated':quality(f).status]].map(([label,fn])=>`<tr><td>${label}</td>${flights.map(f=>`<td>${e(fn(f))}</td>`).join('')}</tr>`).join('')}</table>`);}
function exportTrack(){const f=selected();if(!f)return;const points=f.simulated?scenarioTrack(f.id):live.track(f.id);if(!points.length){toast('No track reports recorded for this aircraft yet.');return;}const quote=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'").replaceAll('"','""')+'"';const head=['callsign','data_mode','timestamp_utc','scenario_seconds','latitude','longitude','barometric_altitude_ft','geometric_altitude_ft','ground_speed_kt','vertical_rate_ft_min','track_deg'];const csv=[head.join(','),...points.map(p=>[p.callsign,p.simulated?'synthetic':'observed',p.simulated?'':new Date(p.positionTime*1000).toISOString(),p.scenarioSeconds??'',p.lat,p.lon,p.altitude,p.geometricAltitude,p.groundSpeed,p.verticalRate,p.track].map(quote).join(','))].join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aeris-'+f.callsign.replace(/[^a-z0-9]/gi,'_')+'-'+(f.simulated?'synthetic':'session')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Track exported with source and units.');}
function togglePlay(){if(state.mode==='live'&&state.replayTime===null){const h=live.track(state.selected);if(h.length<2){toast('Select an aircraft and wait for a second report to replay its track.');return;}state.replayTime=h[0].positionTime;}if(state.mode==='demo'&&state.demoTime>=DEMO_DURATION)state.demoTime=0;state.playing=!state.playing;renderPlayback();}
function locateMe(){if(!navigator.geolocation){toast('Location is not available on this device.');return;}navigator.geolocation.getCurrentPosition(p=>map.flyTo(p.coords.latitude,p.coords.longitude,8.5),()=>toast('Location permission was not granted.'),{maximumAge:600000,timeout:10000});}
const actions={
 explore(){state.nav='explore';state.airport=null;renderNav();renderDetail();},saved(){state.nav='saved';renderNav();renderDetail();if(innerWidth<=800)$('.workspace').classList.add('detail-open');},airports(){state.nav='airports';state.airport=null;renderNav();renderDetail();if(innerWidth<=800)$('.workspace').classList.add('detail-open');},
 nearby(){const c=state.center,all=visibleFlights(),list=all.map(f=>({f,d:distance([c.lat,c.lng],[displayFlight(f).lat,displayFlight(f).lon])})).sort((a,b)=>a.d-b.d).slice(0,80);openDialog('In this part of the sky.',`<p>${list.length} nearest of ${all.length.toLocaleString('en-SG')} aircraft in view and filters${state.mode==='demo'?' · synthetic scenario':''}.</p>${list.length?list.map(({f})=>flightItem(f)).join(''):'<div class="empty">No aircraft here yet. Coverage depends on volunteer receivers.</div>'}`);},
 'zoom-in':()=>map.zoom(2),'zoom-out':()=>map.zoom(.5),north:()=>map.resetNorth(),recenter(){const f=selected();if(f){const d=displayFlight(f);map.flyTo(d.lat,d.lon);}else toast('Select an aircraft to centre it.');},'locate-me':locateMe,
 satellite(){state.mapStyle=state.mapStyle==='satellite'?'map':'satellite';savePref('mapStyle',state.mapStyle);map.setStyle(state.mapStyle);},
 globe(){state.projection=state.projection==='globe'?'mercator':'globe';savePref('projection',state.projection);map.setProjection(state.projection);toast(state.projection==='globe'?'Globe view':'Flat map view');},
 filters:showFilters,layers:showLayers,settings:showSettings,connect:showConnect,sources:showSources,help:showHelp,
 'close-dialog':closeDialog,'toggle-detail':()=>$('.workspace').classList.toggle('detail-open'),'3d':()=>openScene('chase'),map:closeScene,'reset-camera'(){map.resetCamera(selected());if(state.studio)studio?.reset();},
 'scene-style'(){map.setStyle(map.styleName==='satellite'?'map':'satellite');},
 play:togglePlay,rate(){state.rate=state.rate===1?4:state.rate===4?16:1;renderPlayback();},'return-live'(){state.playing=false;if(state.mode==='demo'){state.demoTime=0;state.flights=demoFlights(0);}else state.replayTime=null;refresh();},
 'save-flight'(){const f=selected();if(!f)return;if(state.saved.includes(f.id)){state.saved=state.saved.filter(id=>id!==f.id);delete state.savedMeta[f.id];toast('Removed from saved flights.');}else{state.saved.push(f.id);state.savedMeta[f.id]={...f};toast(f.callsign+' saved on this device.');}savePref('saved',state.saved);savePref('savedMeta',state.savedMeta);renderNav();renderDetail();},
 'clear-saved'(){state.saved=[];state.savedMeta={};savePref('saved',[]);savePref('savedMeta',{});renderNav();renderDetail();toast('Saved list cleared.');},compare,export:exportTrack,
 'apply-filters'(){const min=Number($('#filter-min').value),max=Number($('#filter-max').value);if(!Number.isFinite(min)||!Number.isFinite(max)||min<0||max>60000||min>max){$('#filter-error').textContent='Use altitudes from 0 to 60,000 ft, with minimum no greater than maximum.';return;}state.filter={min,max,type:$('#filter-type').value,ground:$('#filter-ground').checked};pushMap(true);closeDialog();toast(visibleFlights().length.toLocaleString('en-SG')+' aircraft match your filters.');},
 'reset-filters'(){state.filter={min:0,max:60000,type:'all',ground:true};pushMap(true);closeDialog();},
 'save-settings'(){state.units=$('#units').value;state.quality=$('#render-quality').value;savePref('units',state.units);savePref('quality',state.quality);studio?.setQuality(state.quality);closeDialog();refresh();toast('Preferences updated.');},
 'use-demo':useDemo,'use-live':useLive,
 'save-proxy'(){const v=$('#proxy').value.trim();if(v){try{parseEndpoint(v);}catch(err){$('#connection-error').textContent=err.message;return;}}savePref('proxy',v||null);setProxy(v||defaultProxy());closeDialog();if(canLive()&&state.mode==='demo')useLive();else toast(v?'Proxy saved.':'Proxy removed.');}
};
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!ev.target.closest('.search-area'))closeSearch();if(!b)return;
 if(b.dataset.action){actions[b.dataset.action]?.();}
 else if(b.dataset.flight){closeDialog();selectFlight(b.dataset.flight,{fly:Boolean(b.dataset.fly)||!state.view3d});}
 else if(b.dataset.airport){closeDialog();selectAirport(b.dataset.airport);}
 else if(b.dataset.find){findWorldwide(b.dataset.find);}
 else if(b.dataset.tab){state.tab=b.dataset.tab;renderDetail();}
 else if(b.dataset.camera){setCamera(b.dataset.camera);}
 else if(b.dataset.style){state.mapStyle=b.dataset.style;savePref('mapStyle',state.mapStyle);map.setStyle(state.mapStyle);document.querySelectorAll('[data-style]').forEach(x=>x.classList.toggle('active',x===b));}
 else if(b.dataset.metric){const def=definitions[b.dataset.metric];openDialog(def[0],`<p>${def[1]}</p><div class="notice">${selected()?.simulated?'Current values belong to a synthetic demo.':'An unavailable value means the aircraft did not broadcast it.'}</div><button class="primary" data-action="close-dialog">Got it</button>`);}});
document.addEventListener('change',ev=>{const t=ev.target;
 if(t.dataset.layer==='globe'){state.projection=t.checked?'globe':'mercator';savePref('projection',state.projection);map.setProjection(state.projection);}
 else if(t.dataset.layer){map[t.dataset.layer]=t.checked;map.applyLayerToggles();if(t.dataset.layer==='trails')updateTrail(true);}
 else if(t.dataset.provider){live.setEnabled(t.dataset.provider,t.checked);savePref('disabledProviders',PROVIDERS.map(p=>p.id).filter(id=>!live.enabled.has(id)));}});
$('#search').addEventListener('input',search);$('#search').addEventListener('keydown',ev=>{if(ev.key==='Escape')closeSearch();if(ev.key==='Enter')$('#search-results button')?.click();if(ev.key==='ArrowDown'){ev.preventDefault();$('#search-results button')?.focus();}});
$('#timeline').addEventListener('input',ev=>{state.playing=false;if(state.mode==='demo'){state.demoTime=Number(ev.target.value);state.flights=demoFlights(state.demoTime);}else state.replayTime=Number(ev.target.value);refresh();updateTrail(true);});
document.addEventListener('keydown',ev=>{if(['INPUT','TEXTAREA','SELECT'].includes(ev.target.tagName))return;if(ev.key==='/'&&!$('#dialog').open){ev.preventDefault();$('#search').focus();}if(ev.key===' '&&!$('#dialog').open&&ev.target.tagName!=='BUTTON'){ev.preventDefault();togglePlay();}if(ev.key==='Escape'&&!$('#dialog').open){if(state.view3d)closeScene();else if(state.selected)deselect();$('.workspace').classList.remove('detail-open');}});
let pageVisible=true;// browsers stop animation frames in hidden tabs; this tracks explicit changes
document.addEventListener('visibilitychange',()=>{pageVisible=!document.hidden;lastFrame=performance.now();live.setPaused(document.hidden);});

function animate(t){
 const dt=lastFrame?Math.min((t-lastFrame)/1000,.1):0;lastFrame=t;
 if(pageVisible){
  if(state.playing){if(state.mode==='demo'){state.demoTime=Math.min(DEMO_DURATION,state.demoTime+dt*state.rate);state.flights=demoFlights(state.demoTime);if(state.demoTime>=DEMO_DURATION)state.playing=false;}
   else if(state.replayTime!==null){const end=live.track(state.selected).at(-1)?.positionTime||state.replayTime;state.replayTime=Math.min(end,state.replayTime+dt*state.rate);if(state.replayTime>=end)state.playing=false;}}
  const f=selected();
  if(f){const d=displayFlight(f);if(state.view3d)map.update3D(d);map.setSelected(d,iconClass(f));}
  pushMap();updateTrail();
  if(t-lastUI>300){lastUI=t;renderPlayback();renderClock();
   if(f){if(state.nav==='explore'&&state.tab==='overview'){for(const [key,kind] of [['altitude','alt'],['groundSpeed','speed'],['verticalRate','vertical'],['track','°']]){const el=$(`[data-value="${key}"]`);if(el)el.innerHTML=fmt(f[key],kind,kind==='vertical'&&state.units==='metric'?1:0)+`<small>${unit(kind)}</small>`;}if($('#flight-phase'))$('#flight-phase').textContent=phase(f);}
    if($('#detail-data-status'))$('#detail-data-status').textContent=dataStatus(f);
    if(state.view3d){const alt=map.lastAltitude;$('#scene-source').textContent=f.simulated?'SIMULATED FLIGHT':state.replayTime!==null?'SESSION REPLAY':quality(f).status.toUpperCase()+' · '+f.source;if(alt?.metres!=null)$('#scene-fidelity').textContent=`${fmt(alt.metres/FT,'alt')} ${unit('alt')} above sea level · ${alt.basis}`;}}
   else if(state.selected&&state.mode==='live'&&!live.get(state.selected)){toast('The selected aircraft left coverage.');deselect();}
  }
  if(t-lastSlow>2000){lastSlow=t;if(!f&&state.nav==='explore'){const has=visibleFlights().length>0;if(has!==emptyHadAircraft){emptyHadAircraft=has;renderDetail();}}if(f){updateRoute();if(state.nav==='explore'&&state.tab==='overview'&&$('#altitude-chart'))$('#altitude-chart').innerHTML=chart(f);}if(state.nav==='airports'&&state.airport)renderAirports();}
 }
 requestAnimationFrame(animate);
}
// ——— Start ———
if(state.mode==='live')live.start();else state.selected='demo-sq228';
$('#map-credit').innerHTML=map.attribution?.()||'';
refresh();renderClock();requestAnimationFrame(animate);
if(state.mode==='demo'){loadAirports().then(()=>{if(state.selected==='demo-sq228'){state.info={route:demoRoute(state.flights[0])};infoFor='demo-sq228';renderDetail();updateRoute();}});if(!canLive())setTimeout(()=>toast('Showing the demo. Live traffic needs the Aeris app or a data proxy.'),1200);}
// Read by the iOS/Android/browser smoke tests: a compact description of what the app shows.
window.__aerisSelfTest=()=>{const s=live.status();return {hidden:document.hidden,visibility:document.visibilityState,running:live.running,paused:live.paused,circles:live.circles.length,view:live.view,loaded:true,bridge:bridge(),mode:state.mode,map:map.ok,style:map.styleName,aircraft:state.mode==='live'?s.aircraft:state.flights.length,onMap:map.flightsData?.features?.length??0,source:$('#source-text')?.textContent,providers:s.providers.map(p=>({id:p.id,state:p.state,ms:p.ms,aircraft:p.aircraft,error:p.error})),selected:state.selected,view3d:state.view3d};};
window.__aeris={state,live,map,selectFlight,openScene,closeScene,setCamera,useDemo,useLive,deselect};
if('serviceWorker' in navigator&&['http:','https:'].includes(location.protocol)&&location.hostname!=='appassets.androidplatform.net'&&location.hostname!=='localhost'&&location.hostname!=='127.0.0.1')navigator.serviceWorker.register('./sw.js').catch(()=>{});
